arguments.command:
python3 - <<'EOF'
import json, glob

total = 0
for f in sorted(glob.glob('data/*.jsonl')):
    for line in open(f):
        line = line.strip()
        if not line:
            continue
        rec = json.loads(line)
        if rec.get('kind') != 'span':
            continue
        el = rec.get('body', {}).get('span', {}).get('elapsed')
        if el is None:
            continue
        v = el['value']
        u = el['unit']
        if u == 'ms':
            total += v
        elif u == 'us':
            total += v // 1000
        elif u == 's':
            total += v * 1000
        else:
            raise ValueError(u)
print(total)
EOF
